head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gBody > P > id]<br/>GridView Body 의 ID 를 설정합니다.",
    "validation" : [
        "GridView Body 의 ID 를 설정합니다.",
        "속성값은 참고용으로 사용되며 GridView 렌더링 시 엔진에서 부여한 ID 값으로 대체됩니다.",
        "Body 영역과 Body Column 영역은 별도로 정의됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_id.setValue("gBody1");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정
    //  - id 는 gBody(Body 영역) 단위 속성이며 dynamic N 이므로 렌더 시점에만 설정한다.
    //  - Body Column 영역은 col1 ~ col4 로 별도 정의한다.
    let cId = con_id.getValue();
    let lblId = (cId === '') ? '미설정' : cId;
    let attrId = (cId === '') ? '' : ' id="' + cId + '"';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] GridView 하위에 w2:gBody 를 선언하고 Body 영역에만 id 속성을 설정 (Body Column 영역은 col1 ~ col4 로 별도 선언)\n[현재] gBody id = ' + lblId + '\n[절차] 옵션 변경 후 Target 재생성 -> ID 확인\n[확인] 선언한 id 값, 렌더된 Body 영역의 실제 id, 선언한 id 의 DOM 조회 개수, Body 영역/Body Column 영역 요소 id 를 결과창에서 확인"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (gBody 에 id 설정)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:600px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style=""' + attrId + '>';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 렌더된 Body 영역(table) 요소 조회
scwin.getBodyArea = function () {
    return target1.render.querySelector("table[id$='_body_table']");
}



// gBody 에 설정한 id 의 실제 적용 여부 확인
scwin.btn_checkId_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let cId = con_id.getValue();
    let bodyArea = scwin.getBodyArea();
    let bodyCol = bodyArea ? bodyArea.querySelector("tbody > tr > td") : null;
    let declaredCount = (cId === '') ? 0 : document.querySelectorAll("[id='" + cId + "'],[id='mf_" + cId + "']").length;

    bottom.setReturnValue("[1] gBody 에 설정한 id : " + (cId === '' ? '(미설정)' : cId));
    bottom.setReturnValue("[2] 렌더된 Body 영역의 실제 id : " + (bodyArea ? bodyArea.id : '(Body 영역 없음)') + " / 설정한 id 로 조회된 DOM 개수 : " + (cId === '' ? '-' : declaredCount));
    bottom.setReturnValue("[3] Body 영역 요소 id : " + (bodyArea ? bodyArea.id : '-') + " / Body Column 영역 요소 id : " + (bodyCol ? bodyCol.id : '-'));
}
